-- Task instances generated by the schedule engine (packages/lib/schedule.ts).
-- Templates live in code; this table stores the dated, owner-assigned copies.

create table public.tasks (
  id uuid primary key default gen_random_uuid(),
  deal_id uuid not null references public.deals (id) on delete cascade,
  title text not null,
  owner text not null,
  phase public.task_phase not null,
  offset_days int not null,
  due_date date not null,
  done boolean not null default false,
  done_at timestamptz,
  created_at timestamptz not null default now()
);

create index tasks_deal_due_idx on public.tasks (deal_id, due_date);

alter table public.tasks enable row level security;

-- Sellers (deal members) read their deal's tasks; only staff mutate.
create policy "tasks: deal access reads"
  on public.tasks for select to authenticated
  using (public.has_deal_access(deal_id));

create policy "tasks: staff with access manage"
  on public.tasks for all to authenticated
  using (public.is_staff() and public.has_deal_access(deal_id))
  with check (public.is_staff() and public.has_deal_access(deal_id));
